import React, { useEffect, useState } from 'react';
import axios from 'axios';
import './Crud.css';

function Crud() {
    const [tablaSeleccionada, setTablaSeleccionada] = useState('');
    const [parroquias, setParroquias] = useState([]);
    const [form, setForm] = useState({
        nombre: '',
        telefono: '',
        direccion: { calle: '', ciudad: '' },
        niveles_catequesis: [],
    });

    // Fetch parroquias from the backend
    const fetchParroquias = async () => {
        try {
            const res = await axios.get('http://127.0.0.1:5000/api/parroquia');
            setParroquias(res.data);
        } catch (error) {
            console.error('Error fetching parroquias:', error);
        }
    };

    useEffect(() => {
        if (tablaSeleccionada === 'Parroquias') {
            fetchParroquias();
        }
    }, [tablaSeleccionada]);

    // Handle form submission to create a new parroquia
    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            await axios.post('http://127.0.0.1:5000/api/parroquia', form);
            setForm({
                nombre: '',
                telefono: '',
                direccion: { calle: '', ciudad: '' },
                niveles_catequesis: [],
            });
            fetchParroquias();
        } catch (error) {
            console.error('Error creating parroquia:', error);
        }
    };

    return (
        <div className="crud-container">
            <h2 className="crud-title">CRUD - Parroquias</h2>
            <form>
                <label className="form-label" htmlFor="tabla">Selecciona la tabla:</label>
                <select
                    id="tabla"
                    value={tablaSeleccionada}
                    onChange={(e) => setTablaSeleccionada(e.target.value)}
                    required
                >
                    <option value="">-- Selecciona una tabla --</option>
                    <option value="Parroquias">Parroquias</option>
                </select>
            </form>

            {tablaSeleccionada === 'Parroquias' && (
                <>
                    <form onSubmit={handleSubmit}>
                        <label className="form-label">Nombre</label>
                        <input
                            placeholder="Nombre"
                            value={form.nombre}
                            onChange={(e) => setForm({ ...form, nombre: e.target.value })}
                            required
                        />
                        <label className="form-label">Teléfono</label>
                        <input
                            placeholder="Teléfono"
                            value={form.telefono}
                            onChange={(e) => setForm({ ...form, telefono: e.target.value })}
                            required
                        />
                        <label className="form-label">Dirección - Calle</label>
                        <input
                            placeholder="Calle"
                            value={form.direccion.calle}
                            onChange={(e) => setForm({ ...form, direccion: { ...form.direccion, calle: e.target.value } })}
                            required
                        />
                        <label className="form-label">Dirección - Ciudad</label>
                        <input
                            placeholder="Ciudad"
                            value={form.direccion.ciudad}
                            onChange={(e) => setForm({ ...form, direccion: { ...form.direccion, ciudad: e.target.value } })}
                            required
                        />
                        <button type="submit">Crear</button>
                    </form>

                    <div className="documents-container">
                        {parroquias.map((doc) => (
                            <div key={doc._id} className="document-card">
                                <h3>Documento ID: {doc._id}</h3>
                                <p><strong>Nombre:</strong> {doc.nombre}</p>
                                <p><strong>Teléfono:</strong> {doc.telefono}</p>
                                <p><strong>Dirección:</strong> {doc.direccion.calle}, {doc.direccion.ciudad}</p>
                                <p><strong>Niveles Catequesis:</strong></p>
                                <ul>
                                    {doc.niveles_catequesis.map((nivel, index) => (
                                        <li key={index}>
                                            <p><strong>Nombre Nivel:</strong> {nivel.nombre_nivel}</p>
                                            <p><strong>Orden:</strong> {nivel.orden}</p>
                                        </li>
                                    ))}
                                </ul>
                            </div>
                        ))}
                    </div>
                </>
            )}
        </div>
    );
}

export default Crud;
